-- stochastic-processes implementation for LatinHypercube
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.

local Module = {}
function Module.Sample(count,dimensions,uniforms)
    assert(count>=1 and dimensions>=1 and #uniforms==count*dimensions,"invalid Latin hypercube dimensions")
    local result=table.create(count)
    for i=1,count do result[i]=table.create(dimensions) end
    for d=1,dimensions do
        local permutation=table.create(count); for i=1,count do permutation[i]=i end
        for i=count,2,-1 do local j=math.floor(uniforms[(d-1)*count+i]*i)+1; permutation[i],permutation[j]=permutation[j],permutation[i] end
        for i=1,count do local u=uniforms[(d-1)*count+i]; result[i][d]=(permutation[i]-1+u)/count end
    end
    return result
end

return Module
